#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Symbol {
    pub name: &'static str,
    pub path: &'static str,
}

/// The SVG path for a known icon name.
pub fn path(name: &str) -> Option<&'static str> {
    SYMBOLS
        .binary_search_by(|entry| entry.0.cmp(name))
        .ok()
        .map(|index| SYMBOLS[index].4)
}

/// The path for an instance's stored icon, falling back for unknown names
/// (a forward-produced store or a renamed glyph) instead of failing.
pub fn path_or_fallback(name: Option<&str>) -> &'static str {
    name.and_then(path)
        .or_else(|| path(FALLBACK_ICON))
        .unwrap_or("")
}

/// "rocket_launch" → "Rocket launch" for accessible names and tooltips.
pub fn label(name: &str) -> String {
    let words = name.replace('_', " ");
    let mut chars = words.trim().chars();
    match chars.next() {
        Some(first) => first.to_uppercase().chain(chars).collect(),
        None => String::new(),
    }
}

/// Bounded search. Every query word must match the name, a tag or a
/// synonym; name matches rank above tag matches, then Google's popularity.
/// `category` (an index into [`CATEGORIES`]) narrows the set. An empty query
/// shows the curated defaults first, then the most popular icons.
pub fn search(query: &str, category: Option<usize>, limit: usize) -> Vec<Symbol> {
    let words: Vec<String> = query
        .split(|c: char| c.is_whitespace() || c == ',')
        .map(|w| w.trim().to_lowercase().replace(' ', "_"))
        .filter(|w| !w.is_empty())
        .take(6)
        .collect();
    let in_category =
        |entry: &(&str, &str, u8, u32, &str)| category.is_none_or(|c| entry.2 as usize == c);
    if words.is_empty() {
        let mut out: Vec<Symbol> = Vec::with_capacity(limit);
        if category.is_none() {
            for name in DEFAULT_ICONS {
                if let Some(path) = path(name) {
                    out.push(Symbol { name, path });
                }
            }
        }
        let mut popular: Vec<_> = SYMBOLS
            .iter()
            .filter(|e| in_category(e) && !DEFAULT_ICONS.contains(&e.0))
            .collect();
        popular.sort_by(|a, b| b.3.cmp(&a.3).then(a.0.cmp(b.0)));
        out.extend(popular.into_iter().map(|e| Symbol {
            name: e.0,
            path: e.4,
        }));
        out.truncate(limit);
        return out;
    }
    let mut scored: Vec<(u32, u32, &'static str, &'static str)> = Vec::new();
    for entry in SYMBOLS.iter().filter(|e| in_category(e)) {
        let mut total = 0u32;
        let mut all = true;
        for word in &words {
            let score = word_score(entry, word);
            if score == 0 {
                all = false;
                break;
            }
            total += score;
        }
        if all {
            scored.push((total, entry.3, entry.0, entry.4));
        }
    }
    scored.sort_by(|a, b| b.0.cmp(&a.0).then(b.1.cmp(&a.1)).then(a.2.cmp(b.2)));
    scored
        .into_iter()
        .take(limit)
        .map(|(_, _, name, path)| Symbol { name, path })
        .collect()
}

fn word_score(entry: &(&str, &str, u8, u32, &str), word: &str) -> u32 {
    let name = entry.0;
    let mut best = 0;
    if name == word {
        best = 100;
    } else if name.starts_with(word) {
        best = 60;
    } else if name.split('_').any(|part| part == word) {
        best = 50;
    } else if name.contains(word) {
        best = 30;
    }
    if best < 25 {
        for tag in entry.1.split(' ') {
            if tag == word {
                best = best.max(25);
            } else if word.len() >= 3 && tag.starts_with(word) {
                best = best.max(12);
            }
        }
    }
    if best < 40 {
        for (key, names) in SYNONYMS {
            if (*key == word || (word.len() >= 3 && key.starts_with(word))) && names.contains(&name)
            {
                best = best.max(40);
            }
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::*;

    fn names(query: &str) -> Vec<&'static str> {
        search(query, None, RESULT_LIMIT)
            .into_iter()
            .map(|s| s.name)
            .collect()
    }

    #[test]
    fn data_is_sorted_unique_and_valid() {
        assert!(SYMBOLS.len() > 3000, "{}", SYMBOLS.len());
        for pair in SYMBOLS.windows(2) {
            assert!(pair[0].0 < pair[1].0, "{} !< {}", pair[0].0, pair[1].0);
        }
        for entry in SYMBOLS {
            assert!(
                (1..=64).contains(&entry.0.len())
                    && entry
                        .0
                        .bytes()
                        .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_'),
                "{}",
                entry.0
            );
            assert!(entry.4.starts_with('M'), "{}", entry.0);
        }
        for name in DEFAULT_ICONS {
            assert!(path(name).is_some(), "{name}");
        }
        assert!(path(FALLBACK_ICON).is_some());
    }

    #[test]
    fn requested_keywords_find_relevant_icons() {
        assert_eq!(names("sword")[0], "swords");
        assert!(names("combat").contains(&"swords"));
        assert!(names("pvp").contains(&"swords"));
        assert!(names("server").contains(&"dns"));
        assert!(names("tools").contains(&"handyman"));
        assert!(names("rocket launch").contains(&"rocket_launch"));
        assert!(names("zzzz-no-such-icon").is_empty());
    }

    #[test]
    fn empty_queries_start_with_the_defaults_and_stay_bounded() {
        let first: Vec<_> = search("", None, 5).into_iter().map(|s| s.name).collect();
        assert_eq!(first, &DEFAULT_ICONS[..5]);
        assert_eq!(search("", None, RESULT_LIMIT).len(), RESULT_LIMIT);
        assert!(search("a", None, RESULT_LIMIT).len() <= RESULT_LIMIT);
    }

    #[test]
    fn categories_narrow_results() {
        let index = CATEGORIES.iter().position(|c| *c == "Maps").unwrap();
        let all = search("", Some(index), 50);
        assert!(!all.is_empty());
    }

    #[test]
    fn unknown_names_fall_back() {
        assert_eq!(
            path_or_fallback(Some("not_a_real_icon")),
            path(FALLBACK_ICON).unwrap()
        );
        assert_eq!(label("rocket_launch"), "Rocket launch");
    }
}
